package bowling

import "errors"

// Game keeps track of a bowling game in progress.
type Game struct {
	rolls         []int
	frame         int // current frame, 0-based (0-9)
	rollInFrame   int // rolls made in the current frame
	pinsRemaining int // pins still standing in the current frame
	over          bool // true once all 10 frames (and any bonus rolls) are complete
}

func NewGame() *Game {
	return &Game{
		pinsRemaining: 10,
	}
}

func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errors.New("Negative roll is invalid")
	}
	if g.over {
		return errors.New("Cannot roll after game is over")
	}
	if pins > g.pinsRemaining {
		return errors.New("Pin count exceeds pins on the lane")
	}

	g.rolls = append(g.rolls, pins)
	g.pinsRemaining -= pins

	if g.frame == 9 {
		// Tenth frame: strikes and spares earn bonus rolls.
		g.rollInFrame++
		firstRoll := g.rolls[len(g.rolls)-g.rollInFrame]
		switch g.rollInFrame {
		case 1:
			if firstRoll == 10 {
				g.pinsRemaining = 10
			}
		case 2:
			if firstRoll == 10 {
				if pins == 10 {
					g.pinsRemaining = 10
				}
			} else if g.pinsRemaining == 0 {
				g.pinsRemaining = 10
			} else {
				g.over = true
			}
		case 3:
			if firstRoll == 10 && pins == 10 {
				g.pinsRemaining = 10
			} else {
				g.over = true
			}
		default:
			g.over = true
		}
	} else {
		if g.pinsRemaining == 0 {
			// Strike or spare: advance to the next frame.
			g.frame++
			g.rollInFrame = 0
			g.pinsRemaining = 10
			if g.frame == 10 {
				g.over = true
			}
		} else {
			g.rollInFrame = 1
		}
	}

	return nil
}

func (g *Game) Score() (int, error) {
	if !g.over {
		return 0, errors.New("Score cannot be taken until the end of the game")
	}

	rolls := g.rolls
	score := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		if rolls[i] == 10 {
			score += 10 + rolls[i+1] + rolls[i+2]
			i++
		} else if rolls[i]+rolls[i+1] == 10 {
			score += 10 + rolls[i+2]
			i += 2
		} else {
			score += rolls[i] + rolls[i+1]
			i += 2
		}
	}
	return score, nil
}

